from __future__ import annotations

import os
import shutil
import signal
import subprocess
import tempfile
import time
import unittest
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch

from builder import backends
from builder.libtool import patch_archive_locks


# Fixture from GNU libtool 2.6.2, as generated by libsodium's configure.
_LIBTOOL = r'''#!/bin/sh
lock_old_archive_extraction=yes
func_compiler_lock ()
{
  ln "$progpath" "$lockfile" 2>/dev/null
}
func_extract_an_archive ()
{
    $debug_cmd

    f_ex_an_ar_dir=$1; shift
    f_ex_an_ar_oldlib=$1
    if test yes = "$lock_old_archive_extraction"; then
      lockfile=$f_ex_an_ar_oldlib.lock
      until $opt_dry_run || ln "$progpath" "$lockfile" 2>/dev/null; do
	func_echo "Waiting for $lockfile to be removed"
	sleep 2
      done
    fi
    func_show_eval "(cd \$f_ex_an_ar_dir && $AR x \"\$f_ex_an_ar_oldlib\")" \
		   'stat=$?; rm -f "$lockfile"; exit $stat'
    if test yes = "$lock_old_archive_extraction"; then
      $opt_dry_run || rm -f "$lockfile"
    fi
    if ($AR t "$f_ex_an_ar_oldlib" | sort | sort -uc >/dev/null 2>&1); then
     :
    else
      func_fatal_error "object name conflicts in archive: $f_ex_an_ar_dir/$f_ex_an_ar_oldlib"
    fi
}
'''

_HARNESS = r'''
debug_cmd=:
EXIT_FAILURE=1
opt_dry_run=${DRY_RUN:-false}
AR=${TEST_AR:-fake_ar}
lock_old_archive_extraction=${TEST_LOCKS:-yes}
func_echo () { printf '%s\n' "$*"; }
func_fatal_error () { printf '%s\n' "$*" >&2; exit 1; }
func_show_eval ()
{
  $opt_dry_run && return 0
  eval "$1"
  _G_status=$?
  if test "$_G_status" -ne 0; then
    eval "(exit $_G_status); $2"
  fi
}
# Any attempted link is an error, even on the local test filesystem.
ln () { printf 'unexpected link attempt\n' >&2; exit 91; }
fake_ar ()
{
  if test "$1" = t; then
    printf '%s\n' object.o
    test -z "$DUPLICATE" || printf '%s\n' object.o
    return 0
  fi
  if test -n "$ACTIVE"; then
    mkdir "$ACTIVE" || return 92
    printf '%s\n' "$TOKEN" >> "$STARTED"
    while test ! -f "$RELEASE"; do sleep 0.02; done
    rmdir "$ACTIVE" || return 93
  fi
  return "${EXTRACT_STATUS:-0}"
}
if test -n "$FAST_WAIT"; then
  sleep () { :; }
fi
if test -n "$DENY_MKDIR"; then
  mkdir () { return 1; }
fi
func_extract_an_archive "$1" "$2"
printf 'completed\n'
'''


@unittest.skipIf(os.name == "nt", "requires a POSIX shell")
class LibtoolLockTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)
        self.libtool = self.root / "libtool"
        self.libtool.write_text(_LIBTOOL, encoding="utf-8")
        self.archive = self.root / "archive with spaces.a"
        self.lock = Path(f"{self.archive}.lock")
        self.extract_dir = self.root / "extract with spaces"
        self.extract_dir.mkdir()

    def _command(self):
        patch_archive_locks(self.root)
        harness = self.root / "probe.sh"
        harness.write_text(self.libtool.read_text(encoding="utf-8") + _HARNESS, encoding="utf-8")
        return ["sh", str(harness), str(self.extract_dir), str(self.archive)]

    def _run(self, **overrides):
        return subprocess.run(
            self._command(), env={**os.environ, **overrides},
            text=True, capture_output=True, timeout=5,
        )

    def _spawn(self, **overrides):
        process = subprocess.Popen(
            self._command(), env={**os.environ, **overrides},
            text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            start_new_session=True,
        )
        self.addCleanup(self._stop, process)
        return process

    @staticmethod
    def _stop(process):
        if process.poll() is None:
            os.killpg(process.pid, signal.SIGTERM)
        process.communicate(timeout=5)

    def _wait_for(self, predicate):
        deadline = time.monotonic() + 5
        while not predicate():
            if time.monotonic() >= deadline:
                self.fail("timed out waiting for archive extraction")
            time.sleep(0.02)

    def test_patch_is_idempotent_and_preserves_compiler_lock_and_mode(self):
        self.libtool.chmod(0o755)
        self.assertTrue(patch_archive_locks(self.root))
        patched = self.libtool.read_text(encoding="utf-8")
        self.assertIn('  ln "$progpath" "$lockfile" 2>/dev/null', patched)
        self.assertEqual(self.libtool.stat().st_mode & 0o777, 0o755)
        self.assertFalse(patch_archive_locks(self.root))
        self.assertEqual(self.libtool.read_text(encoding="utf-8"), patched)

    def test_dry_run_missing_libtool_and_disabled_archive_lock_are_unchanged(self):
        self.assertFalse(patch_archive_locks(self.root, dry_run=True))
        self.assertEqual(self.libtool.read_text(encoding="utf-8"), _LIBTOOL)
        unlocked = _LIBTOOL.replace("lock_old_archive_extraction=yes", "lock_old_archive_extraction=no")
        self.libtool.write_text(unlocked, encoding="utf-8")
        self.assertFalse(patch_archive_locks(self.root))
        self.assertEqual(self.libtool.read_text(encoding="utf-8"), unlocked)
        self.libtool.unlink()
        self.assertFalse(patch_archive_locks(self.root))

    def test_unknown_function_is_rejected_without_rewriting(self):
        unknown = _LIBTOOL.replace("sleep 2", "sleep 3")
        self.libtool.write_text(unknown, encoding="utf-8")
        with self.assertRaisesRegex(RuntimeError, "Unsupported libtool"):
            patch_archive_locks(self.root)
        self.assertEqual(self.libtool.read_text(encoding="utf-8"), unknown)

    def test_extract_succeeds_without_any_link_calls_and_releases_lock(self):
        result = self._run()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("completed", result.stdout)
        self.assertFalse(self.lock.exists())

    def test_real_archive_extract_handles_paths_with_spaces(self):
        ar = shutil.which("ar")
        cc = shutil.which("cc")
        if ar is None or cc is None:
            self.skipTest("ar and cc are required for the archive probe")
        member = self.root / "object.o"
        subprocess.run(
            [cc, "-x", "c", "-c", "-o", str(member), "-"],
            input="int archive_probe(void) { return 0; }\n", text=True,
            check=True, capture_output=True,
        )
        subprocess.run([ar, "cr", str(self.archive), str(member)], check=True, capture_output=True)
        result = self._run(TEST_AR=ar)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual((self.extract_dir / member.name).read_bytes(), member.read_bytes())
        self.assertFalse(self.lock.exists())

    def test_extraction_failure_propagates_and_releases_owned_lock(self):
        result = self._run(EXTRACT_STATUS="7")
        self.assertEqual(result.returncode, 7, result.stderr)
        self.assertNotIn("completed", result.stdout)
        self.assertFalse(self.lock.exists())

    def test_archive_conflicts_fail_and_release_lock(self):
        result = self._run(DUPLICATE="yes")
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("object name conflicts", result.stderr)
        self.assertFalse(self.lock.exists())

    def test_dry_run_does_not_acquire_or_remove_an_existing_lock(self):
        self.lock.mkdir()
        result = self._run(DRY_RUN="true")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertTrue(self.lock.is_dir())

    def test_disabled_lock_does_not_remove_someone_elses_lock(self):
        self.lock.mkdir()
        result = self._run(TEST_LOCKS="no")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertTrue(self.lock.is_dir())

    def test_stale_directory_and_legacy_file_locks_fail_without_deleting_them(self):
        self.lock.mkdir()
        result = self._run(FAST_WAIT="yes")
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("Cannot acquire archive extraction lock", result.stderr)
        self.assertTrue(self.lock.is_dir())
        self.lock.rmdir()
        self.lock.write_text("legacy lock", encoding="utf-8")
        result = self._run(FAST_WAIT="yes")
        self.assertNotEqual(result.returncode, 0)
        self.assertEqual(self.lock.read_text(encoding="utf-8"), "legacy lock")

    def test_filesystem_lock_failure_is_bounded(self):
        result = self._run(FAST_WAIT="yes", DENY_MKDIR="yes")
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("Cannot acquire archive extraction lock", result.stderr)
        self.assertFalse(self.lock.exists())

    def test_concurrent_extractors_are_serialized(self):
        started = self.root / "started"
        release = self.root / "release"
        shared = dict(ACTIVE=str(self.root / "active"), STARTED=str(started), RELEASE=str(release))
        first = self._spawn(**shared, TOKEN="first")
        self._wait_for(started.exists)
        self.assertTrue(self.lock.is_dir())
        second = self._spawn(**shared, TOKEN="second")
        # The second process cannot enter extraction while the first holds it.
        time.sleep(0.15)
        self.assertIsNone(second.poll())
        self.assertEqual(started.read_text(encoding="utf-8"), "first\n")
        release.touch()
        first_out, first_err = first.communicate(timeout=5)
        second_out, second_err = second.communicate(timeout=5)
        self.assertEqual(first.returncode, 0, first_err)
        self.assertEqual(second.returncode, 0, second_err)
        self.assertIn("completed", first_out)
        self.assertIn("Waiting for", second_out)
        self.assertEqual(started.read_text(encoding="utf-8"), "first\nsecond\n")
        self.assertFalse(self.lock.exists())

    def test_termination_releases_owned_lock(self):
        started = self.root / "started"
        process = self._spawn(
            ACTIVE=str(self.root / "active"), STARTED=str(started),
            RELEASE=str(self.root / "never-release"), TOKEN="terminated",
        )
        self._wait_for(started.exists)
        self.assertTrue(self.lock.is_dir())
        os.killpg(process.pid, signal.SIGTERM)
        process.communicate(timeout=5)
        self.assertNotEqual(process.returncode, 0)
        self.assertFalse(self.lock.exists())


class AutotoolsLibtoolIntegrationTests(unittest.TestCase):
    def test_build_and_install_only_patch_after_configure_before_make(self):
        for install_only in (False, True):
            with self.subTest(install_only=install_only), tempfile.TemporaryDirectory() as tmp:
                root = Path(tmp)
                ctx = SimpleNamespace(
                    repo=SimpleNamespace(name="libsodium"), src_dir=root,
                    build_dir=root, install_prefix=root / "prefix", build_type="Debug",
                )
                (root / "configure").touch()
                (root / "Makefile").touch()
                builder = SimpleNamespace(
                    platform=SimpleNamespace(os="macos"), dry_run=False,
                    _jobs=lambda: 8, _repo_log_path=lambda *args: root / "log",
                )
                events = []

                def configure_or_make(cmd, **kwargs):
                    if cmd[0] == "configure":
                        (root / "libtool").write_text(_LIBTOOL, encoding="utf-8")
                    else:
                        self.assertIn("directory-based archive extraction lock", (root / "libtool").read_text(encoding="utf-8"))
                    events.append(cmd)

                with (
                    patch.object(backends, "_prepare_autotools_build_dir"),
                    patch.object(backends, "_autotools_build_env", side_effect=lambda b, c, e: e),
                    patch.object(backends, "_autotools_args", return_value=[]),
                    patch.object(backends, "_autotools_linkage_args", return_value=[]),
                    patch.object(backends, "_autotools_configure_command", return_value=["configure"]),
                    patch.object(backends, "_autotools_make_command", side_effect=lambda b, args, e: ["make", *args]),
                    patch.object(backends, "run", side_effect=configure_or_make),
                ):
                    if install_only:
                        self.assertTrue(backends._autotools_install_only(builder, ctx, {}))
                        self.assertEqual(events, [["configure"], ["make", "install"]])
                    else:
                        backends._build_autotools(builder, ctx, {})
                        self.assertEqual(events, [["configure"], ["make", "-j8"], ["make", "install"]])


if __name__ == "__main__":
    unittest.main()
